To merge two sorted singly linked lists into a single sorted linked list in C++, you can follow these steps:

1. Create a new linked list to store the merged result.
2. Use two pointers to traverse the two input linked lists.
3. Compare the current nodes of both lists and append the smaller node to the new linked list.
4. Move the pointer of the list from which the node was taken.
5. Continue this process until one of the lists is exhausted.
6. Append the remaining nodes of the non-exhausted list to the new linked list.

Here's the C++ code to achieve this:

```cpp
#include <iostream>

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class Solution {
public:
    ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {
        // Create a dummy node to simplify the merge process
        ListNode dummy(0);
        ListNode* tail = &dummy;

        // Traverse both lists and merge them
        while (l1 != nullptr && l2 != nullptr) {
            if (l1->val < l2->val) {
                tail->next = l1;
                l1 = l1->next;
            } else {
                tail->next = l2;
                l2 = l2->next;
            }
            tail = tail->next;
        }

        // Append the remaining nodes of l1 or l2
        if (l1 != nullptr) {
            tail->next = l1;
        } else {
            tail->next = l2;
        }

        // Return the merged list, which starts from dummy.next
        return dummy.next;
    }
};

// Helper function to print the linked list
void printList(ListNode* node) {
    while (node != nullptr) {
        std::cout << node->val << " ";
        node = node->next;
    }
    std::cout << std::endl;
}

// Helper function to create a linked list from an array
ListNode* createList(const std::vector<int>& values) {
    ListNode* head = nullptr;
    ListNode* tail = nullptr;
    for (int val : values) {
        ListNode* newNode = new ListNode(val);
        if (head == nullptr) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }
    return head;
}

int main() {
    // Create two sorted linked lists
    std::vector<int> list1 = {1, 3, 5, 7};
    std::vector<int> list2 = {2, 4, 6, 8};

    ListNode* l1 = createList(list1);
    ListNode* l2 = createList(list2);

    // Merge the two lists
    Solution solution;
    ListNode* mergedList = solution.mergeTwoLists(l1, l2);

    // Print the merged list
    printList(mergedList);

    return 0;
}
```

In this code:
- `ListNode` is the structure representing a node in the singly linked list.
- `mergeTwoLists` is the function that merges two sorted linked lists.
- `printList` is a helper function to print the linked list.
- `createList` is a helper function to create a linked list from a vector of integers.
- The `main` function demonstrates how to create two sorted linked lists, merge them, and print the result.

